/**
 * Shader of the smoke swirls.
 *
 * ## The mathematical idea
 *
 * A fractal noise advected by an approximate curl: four reads of the noise
 * around the point give its gradient by finite differences, and the gradient
 * turned by a quarter turn is a divergence-free field — a flow that swirls
 * without ever compressing. The slow rise comes from a plain offset of the
 * domain downwards as time passes.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the background.
 * - `uColorB` — the hue of the body of the smoke.
 * - `uColorC` — the hue of the densest crests.
 * - `uSpeed` — speed of the swirl.
 * - `uScale` — scale of the pattern; higher is finer.
 * - `uLift` — speed of the rise.
 * - `uOctaves` — detail of the noise, and therefore its cost.
 */
export const SMOKE_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uSpeed;
uniform float uScale;
uniform float uLift;
uniform float uOctaves;

// Pseudo-random number: projection onto an arbitrary direction, amplified sine,
// fractional part.
float smokeHash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Value noise: smoothed interpolation between the four corners of the cell.
float smokeNoise(vec2 p) {
  vec2 cell = floor(p);
  vec2 local = fract(p);

  // 3t2 - 2t3: zero derivative at the ends, hence no visible ridge.
  vec2 smoothed = local * local * (3.0 - 2.0 * local);

  float a = smokeHash(cell);
  float b = smokeHash(cell + vec2(1.0, 0.0));
  float c = smokeHash(cell + vec2(0.0, 1.0));
  float d = smokeHash(cell + vec2(1.0, 1.0));

  return mix(mix(a, b, smoothed.x), mix(c, d, smoothed.x), smoothed.y);
}

// Sum of octaves: each pass twice as fine and twice as weak.
float smokeFbm(vec2 p, int octaves) {
  float total = 0.0;
  float amplitude = 0.5;
  float normalisation = 0.0;

  for (int i = 0; i < 6; i += 1) {
    if (i >= octaves) break;
    total += smokeNoise(p) * amplitude;
    normalisation += amplitude;
    p *= 2.0;
    amplitude *= 0.5;
  }

  return total / max(normalisation, 0.0001);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  int octaves = int(clamp(uOctaves, 1.0, 6.0));

  // The rise: the domain slides downwards, so the matter appears to go up.
  vec2 p = vec2(vUv.x * aspect, vUv.y - uTime * uLift * 0.1) * max(uScale, 0.1);
  float t = uTime * uSpeed;

  // Approximate curl: the gradient of the noise by finite differences — two
  // pairs of offset reads — turned by a quarter turn. A field built this way is
  // divergence-free: it swirls without compressing.
  float e = 0.35;
  float gx = smokeFbm(p + vec2(e, 0.0), octaves) - smokeFbm(p - vec2(e, 0.0), octaves);
  float gy = smokeFbm(p + vec2(0.0, e), octaves) - smokeFbm(p - vec2(0.0, e), octaves);
  vec2 curl = vec2(gy, -gx);

  // The matter is the same noise, read where the curl has pushed it. Time
  // enters only the displacement: the smoke deforms, it does not flicker.
  float density = smokeFbm(p + curl * (1.2 + 0.6 * sin(t * 0.5)) + vec2(t * 0.08, 0.0), octaves);

  // Soft contrast: the ramp is wide, the smoke has no hard edge.
  float body = smoothstep(0.30, 0.80, density);

  vec3 colour = mix(uColorA, uColorB, body);
  colour = mix(colour, uColorC, smoothstep(0.62, 0.95, density) * 0.6);

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Smoke: swirls advected by an approximate curl, rising.
 *
 * ## The principle
 *
 * The gradient of the noise, obtained from offset reads, is turned by a quarter turn: the resulting field swirls without ever compressing.
 *
 * Time enters only the displacement, never the colour: the smoke deforms instead of flickering.
 *
 * ## What this component delegates
 *
 * It carries only what sets it apart: its shader, its settings and its
 * fallback. Reading the tokens, converting them to floats and re-reading them
 * when the theme changes all come from the engine — copying that here would
 * leave as many versions to maintain as there are backgrounds.
 *
 * The fallback is not a precaution: it is shown while the backend loads, when
 * WebGL is missing, when the arbiter refuses the surface — it grants only one
 * per backend — and under reduced motion.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { SMOKE_FRAGMENT } from './smoke.shader.js'

/** What the escape hatch receives. */
export interface SmokeControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Props specific to this component. */
export interface SmokeOwnProps {
  /** Speed of the swirl. @defaultValue 0.15 */
  speed?: number
  /** Scale of the pattern. Higher is finer. @defaultValue 2 */
  scale?: number
  /** Speed of the rise. @defaultValue 0.35 */
  lift?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<SmokeControls>
}

/** All props. */
export type SmokeProps = Customisable<SmokeOwnProps>

/** Tokens used by default: the background, the body of the smoke, its crests. */
const DEFAULT_TOKENS = ['--o-theme-bg', '--o-theme-muted', '--o-theme-fg'] as const

/** Default fallback: a frozen tint, in the same tones. */
const DEFAULT_FALLBACK = 'o-bg-zinc-50 dark:o-bg-zinc-950'

/**
 * Noise detail outside low quality.
 *
 * The curl asks for four reads of the noise, plus one for the matter: every
 * octave is therefore paid five times over. It is the only cost lever of the
 * shader, and it does not need to be a prop to be degraded.
 */
const OCTAVES = 4

/** Noise detail at low quality. */
const LOW_OCTAVES = 2

/**
 * Smoke.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Smoke className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Smoke({
  speed = 0.15,
  scale = 2,
  lift = 0.35,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: SmokeProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: SMOKE_FRAGMENT,
    colors,
    uniforms: { uSpeed: speed, uScale: scale, uLift: lift, uOctaves: OCTAVES },
    name: 'smoke',
    // The octaves are the setting that weighs — every octave is paid five times
    // over, four for the curl and one for the matter — hence the only bound one.
    degrade: (quality) => ({
      uOctaves: quality === 'low' ? LOW_OCTAVES : OCTAVES,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
